import{_ as a,o as t,c as i,a0 as o}from"./chunks/framework.CIWPqrYr.js";const s="/manual/assets/02-dashboard.CA_AJRUZ.png",u=JSON.parse('{"title":"4. Staying Updated & Navigating","description":"","frontmatter":{},"headers":[],"relativePath":"04-staying-updated.md","filePath":"04-staying-updated.md"}'),n={name:"04-staying-updated.md"};function r(l,e,d,c,h,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="_4-staying-updated-navigating" tabindex="-1">4. Staying Updated &amp; Navigating <a class="header-anchor" href="#_4-staying-updated-navigating" aria-label="Permalink to &quot;4. Staying Updated &amp; Navigating&quot;">​</a></h1><p>As your workspace grows, keeping track of everything becomes crucial. Stratos offers several centralized hubs to manage your attention.</p><h2 id="the-dashboard-overview" tabindex="-1">The Dashboard Overview <a class="header-anchor" href="#the-dashboard-overview" aria-label="Permalink to &quot;The Dashboard Overview&quot;">​</a></h2><p>Whenever you log in or click the Stratos logo, you land on your personalized <strong>Dashboard</strong>.</p><p><img src="'+s+`" alt="Dashboard Overview"></p><ul><li><strong>Metrics &amp; Analytics</strong>: See exactly how many tasks you have open, what is overdue, and what you&#39;ve completed this week.</li><li><strong>My Recent Tasks</strong>: Jump right back into the tasks you were working on yesterday without hunting through project boards.</li></ul><h2 id="managing-the-inbox" tabindex="-1">Managing the Inbox <a class="header-anchor" href="#managing-the-inbox" aria-label="Permalink to &quot;Managing the Inbox&quot;">​</a></h2><p>The <strong>Inbox</strong> (accessible from the left sidebar) is your personal notification center.</p><ol><li>When someone <code>@mentions</code> you, assigns a task to you, or replies to a thread you follow, a notification appears here.</li><li>Click on a notification to view the context directly inside the Inbox side-panel.</li><li>Once you have read and processed the update, click <strong>Mark as Read</strong> (or the checkmark icon) to clear it from your active list.</li><li><strong>Where did it go?</strong> Your Inbox has two tabs: <em>Active</em> and <em>Cleared</em>. If you accidentally mark something as read, click the <em>Cleared</em> tab, find the notification, and click <strong>Mark as Unread</strong> to move it back.</li></ol><h3 id="task-followers-email-notifications" tabindex="-1">Task Followers &amp; Email Notifications <a class="header-anchor" href="#task-followers-email-notifications" aria-label="Permalink to &quot;Task Followers &amp; Email Notifications&quot;">​</a></h3><p>You can opt-in to follow a task without being the assignee by clicking the <strong>Follow Task</strong> button in the task&#39;s properties sidebar.</p><ul><li><strong>In-App Notifications</strong>: Followers will automatically receive Inbox notifications for <strong>new comments only</strong>. Status updates, due date changes, or priority changes do <em>not</em> currently trigger notifications for followers (only assignees are notified of major state changes).</li><li><strong>Email Notifications</strong>: To prevent spam, Stratos enforces a strict anti-spam rule: it <em>only</em> dispatches an email notification if you are explicitly <code>@mentioned</code> in the comment (e.g., <code>@steve I finished the design.</code>). This is a hardcoded system rule and cannot currently be overridden in user preferences to receive emails for all comments.</li></ul><h4 id="configuring-email-providers-admin" tabindex="-1">Configuring Email Providers (Admin) <a class="header-anchor" href="#configuring-email-providers-admin" aria-label="Permalink to &quot;Configuring Email Providers (Admin)&quot;">​</a></h4><p>Emails are routed instantly via SMTP, Amazon SES, or Resend. Administrators must configure these via server environment variables (<code>.env</code> file) before startup. The system will cascade and select the first available provider:</p><ol><li><strong>SMTP (Nodemailer)</strong>: Requires <code>SMTP_HOST</code> and <code>SMTP_USER</code> (plus <code>SMTP_PORT</code> and <code>SMTP_PASS</code>).</li><li><strong>Amazon SES (v3)</strong>: Used if SMTP is not set. Requires <code>AWS_REGION</code> and <code>AWS_ACCESS_KEY_ID</code> (plus <code>AWS_SECRET_ACCESS_KEY</code>).</li><li><strong>Resend API</strong>: Fallback if neither SMTP nor SES are configured. Requires <code>RESEND_API_KEY</code>.</li></ol><h2 id="the-helpdesk" tabindex="-1">The Helpdesk <a class="header-anchor" href="#the-helpdesk" aria-label="Permalink to &quot;The Helpdesk&quot;">​</a></h2><p>The <strong>Helpdesk</strong> module is designed for teams that process inbound requests (like IT support or client requests).</p><h3 id="configuring-helpdesk-webhooks" tabindex="-1">Configuring Helpdesk Webhooks <a class="header-anchor" href="#configuring-helpdesk-webhooks" aria-label="Permalink to &quot;Configuring Helpdesk Webhooks&quot;">​</a></h3><p>Instead of manually creating tasks, external tools can create tasks on your board automatically.</p><ol><li>Navigate to <strong>Board Settings -&gt; Integrations</strong>.</li><li>Under &quot;Helpdesk&quot;, click <strong>Generate Webhook URL</strong>.</li><li>Send a standard HTTP POST request to this URL with a JSON payload containing <code>title</code>, <code>description</code>, and <code>requester_email</code>.<div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Server outage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;The production server is down.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;requester_email&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;client@example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li>These tasks arrive in a special &quot;Helpdesk Triage&quot; queue. They are triaged by a designated manager before being converted into standard tasks and assigned to the team.</li></ol><h2 id="global-search-command-palette" tabindex="-1">Global Search &amp; Command Palette <a class="header-anchor" href="#global-search-command-palette" aria-label="Permalink to &quot;Global Search &amp; Command Palette&quot;">​</a></h2><p>Don&#39;t want to click through menus? Use the Command Palette.</p><ul><li>Press <code>Cmd + K</code> (Mac) or <code>Ctrl + K</code> (Windows) anywhere in the app.</li><li>Type the name of a project, board, or task.</li><li>Instantly navigate to your destination.</li></ul>`,23)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
